theorem convertVec_preserves_solution_set (c : VectorConstraint) :
    {x : List Int | VectorConstraintSat c x} =
    {x : List Int | LayerOut (convertVec c) x = 0}

theorem sq_eq_zero_of_localMin {f : E → ℝ} {f' : E →L[ℝ] ℝ} {x : E}
    (hderiv : HasFDerivAt f f' x) (hne : f' ≠ 0)
    (hmin : IsLocalMin (fun y => f y ^ 2) x) : f x = 0

theorem IdempotentOn.iterate {α : Type} {S : α → Prop} {g : α → α}
    (h : IdempotentOn S g) (n : ℕ) :
    IdempotentOn S (g^[n])

theorem sim_comp {S T U L : Type*}
    {R : S → L → S → Prop} {R' : T → L → T → Prop} {R'' : U → L → U → Prop}
    {φ : S → T} {ψ : T → U}
    (hφ : ForwardSim R R' φ) (hψ : ForwardSim R' R'' ψ) :
    ForwardSim R R'' (ψ ∘ φ)

theorem sim_mono {S T L : Type*}
    {R : S → L → S → Prop} {R' R'' : T → L → T → Prop} {φ : S → T}
    (h : ForwardSim R R' φ) (hsub : ∀ a l b, R' a l b → R'' a l b) :
    ForwardSim R R'' φ

theorem runs_preserved {S T L : Type*}
    {R : S → L → S → Prop} {R' : T → L → T → Prop} {φ : S → T}
    (h : ForwardSim R R' φ) {s t : S} {ls : List L} (hs : StarAny R s ls t) :
    StarAny R' (φ s) ls (φ t)

theorem coordDiff_sub_le {n k : ℕ} {pts pts' : ℕ → Pt n} {a b : ℕ}
    (ha : a < k) (hb : b < k) (i : Fin n) :
    |(pts a i - pts b i) - (pts' a i - pts' b i)| ≤ 2 * rho n k pts pts'
